#include <stdio.h>

#define SIZE 4

typedef struct { int buf[SIZE]; int head, tail, count; } Queue;

int put(Queue *q, int v)
{
    if (q->count == SIZE) return 0;      /* full */
    q->buf[q->tail] = v;
    q->tail = (q->tail + 1) % SIZE;
    q->count++;
    return 1;
}

int get(Queue *q, int *out)
{
    if (q->count == 0) return 0;         /* empty */
    *out = q->buf[q->head];
    q->head = (q->head + 1) % SIZE;
    q->count--;
    return 1;
}

int main(void)
{
    Queue q = {0};
    for (int patient = 1; patient <= 5; patient++)
        if (!put(&q, patient)) printf("patient %d: queue full, come back later\n", patient);
    int p;
    get(&q, &p); printf("serving %d\n", p);
    put(&q, 6);                          /* wraps around to slot 0 */
    while (get(&q, &p)) printf("serving %d\n", p);
    return 0;
}

