typedef struct {
    int *data;
    int len;    /* the top of the stack is data[len - 1] */
    int cap;
} Stack;

void stack_init(Stack *s)
{
    s->data = NULL;
    s->len = 0;
    s->cap = 0;
}

void stack_free(Stack *s)
{
    my_free(s->data);
    s->data = NULL;
    s->len = 0;
    s->cap = 0;
}

int stack_push(Stack *s, int move)
{
    if (s->len == s->cap) {
        int new_cap = s->cap ? s->cap * 2 : 4;
        int *tmp = my_realloc(s->data, new_cap * sizeof *tmp);
        if (tmp == NULL) return 0;
        s->data = tmp;
        s->cap = new_cap;
    }
    s->data[s->len++] = move;
    return 1;
}

int stack_pop(Stack *s, int *out)
{
    if (s->len == 0) return 0;      /* nothing to undo */
    *out = s->data[--s->len];
    return 1;
}

