#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Archie's counting helpers: use these instead of malloc/realloc/free so the tests can see leaks. */
int live_allocs = 0;          /* blocks handed out and not yet freed */
size_t last_alloc_size = 0;   /* size of the most recent allocation */

void *my_alloc(size_t size)
{
    void *p = malloc(size);
    if (p != NULL) {
        live_allocs++;
        last_alloc_size = size;
    }
    return p;
}

void *my_realloc(void *p, size_t size)
{
    void *q = realloc(p, size);
    if (q != NULL) {
        if (p == NULL) live_allocs++;   /* realloc(NULL, n) is a new block */
        last_alloc_size = size;
    }
    return q;
}

void my_free(void *p)
{
    if (p != NULL) {
        live_allocs--;
        free(p);
    }
}

int brackets_ok(const char *s)
{
    size_t n = strlen(s);
    if (n == 0) return 1;
    char *stack = my_alloc(n);          /* never more openers than characters */
    if (stack == NULL) return 0;
    size_t top = 0;
    int ok = 1;
    for (size_t i = 0; i < n && ok; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            char want = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (top == 0 || stack[top - 1] != want) ok = 0;
            else top--;
        }
    }
    if (top != 0) ok = 0;               /* something was never closed */
    my_free(stack);
    return ok;
}

