#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RING_SIZE 8

typedef struct {
    unsigned char buf[RING_SIZE];
    int head;    /* where the next byte is read from */
    int tail;    /* where the next byte is written to */
    int count;   /* how many bytes are waiting */
} Ring;

int ring_put(Ring *r, unsigned char b)
{
    if (r->count == RING_SIZE) return 0;    /* full: drop the new byte */
    r->buf[r->tail] = b;
    r->tail = (r->tail + 1) % RING_SIZE;     /* wrap after the last slot */
    r->count++;
    return 1;
}

int ring_get(Ring *r, unsigned char *out)
{
    if (r->count == 0) return 0;            /* nothing waiting */
    *out = r->buf[r->head];
    r->head = (r->head + 1) % RING_SIZE;
    r->count--;
    return 1;
}
